#pragma once

#include <stdint.h>

#include "../autogenerated_layouts.h"
#include "../data/CoordConvert.h"

// An oriented bounding box (Ghidra: OBB, 0xb0 bytes, 16-byte aligned on the stack): the physics' separating-axis
// test between two boxes - rigid bodies against placed objects and the world's boxes, triggers, missiles, shells.
// Built from a matrix (its first three rows are the box's axes), a centre and the half extents along the axes;
// the overlap test with intersection records the deepest penetration found, where and along which axis.
struct OBB {
    Coord4 centre;              // +0x00
    Coord4 axis[3];             // +0x10 the matrix's rows 0-2 (x, y, z copied; w left as it was)
    Coord4 extentAxis[3];       // +0x40 axis[i] * halfExtent[i] (w left as it was)
    Coord4 contactPoint;        // +0x70 CheckOBBOverlapAndFindIntersection's: the other box's corner (w cleared by Reset)
    Coord4 normal;              // +0x80 the separating axis of the deepest penetration (w cleared by Reset)
    float penetration;          // +0x90 the deepest so far (negative: the axis with the least overlap); -100000 after Reset
    uint8_t secondPass;         // +0x94 the penetration was found along the other box's axis
    uint8_t unknown95[0xb];
    float halfExtent[3];        // +0xa0
    uint32_t unknownAC;

    OBB* Construct();                                                                   // 0x00037a70
    // OBB::OBB(MATRIX4 *, COORD4 *, COORD4 *) (0x000ac870; Ghidra calls it Reset, but it answers this, and its
    // callers use it as the constructor - one on memory fresh from operator new)
    OBB* Construct(const MATRIX4 *matrix, const Coord4 *position, const Coord4 *halfExtents);
    void Reset(const MATRIX4 *matrix, const Coord4 *position, const Coord4 *halfExtents);      // 0x000ac970
    bool CheckOBBOverlap(const OBB *other) const;                                       // 0x000aca70
    bool CheckOBBOverlapAndFindIntersection(const OBB *other);                          // 0x000acb90
};
static_assert(sizeof(OBB) == 0xb0, "OBB is 0xb0 bytes");
